LEVEL = 1
CFG = {1: {"cap": 3, "failures": 2}, 2: {"cap": 5, "failures": 4}, 3: {"cap": 5, "failures": 9}}
cap, failures = CFG[LEVEL]["cap"], CFG[LEVEL]["failures"]
attempts, calls = 0, {"n": 0}
def flaky():
    calls["n"] += 1
    if calls["n"] <= failures:
        raise IOError("transient")
    return "ok"
result = None
for attempts in range(1, cap + 1):
    try:
        result = flaky(); break
    except IOError:
        result = "gave up after %d attempts" % attempts
print("result:", result, "| calls made:", calls["n"])

