LEVEL = 1
CFG = {1: {"budget": 5, "wanted": 8}, 2: {"budget": 10, "wanted": 14}, 3: {"budget": 20, "wanted": 25}}
budget, wanted = CFG[LEVEL]["budget"], CFG[LEVEL]["wanted"]
spent, allowed, denied = 0, 0, 0
for _ in range(wanted):
    if spent < budget:
        spent += 1; allowed += 1
    else:
        denied += 1
print("budget:", budget, "| allowed:", allowed, "| denied:", denied, "| retry ratio capped at %.0f%%" % (100.0 * budget / wanted))

