LEVEL = 1
CFG = {1: {"threshold": 3}, 2: {"threshold": 4}, 3: {"threshold": 5}}
TH = CFG[LEVEL]["threshold"]
state, fails, log = "closed", 0, []
plan = ["fail"] * (TH + 1) + ["cooldown", "probe-ok"]
for step in plan:
    if state == "open":
        if step == "cooldown":
            state = "half-open"; log.append("half-open probe allowed")
        else:
            log.append("fast-fail (open)"); continue
    if step == "fail":
        fails += 1; log.append("fail %d/%d" % (fails, TH))
        if fails >= TH: state = "open"; log.append("circuit OPEN")
    elif step == "probe-ok":
        state = "closed"; fails = 0; log.append("probe ok -> CLOSED")
print("final state:", state)
print("transitions:", " | ".join(log))

